using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Entity;
using System.Data.SqlClient;
using System.Linq;
using System.Linq.Expressions;
using System.Text;
using Dapper;
using PerformanceTest;
using PerformanceTest.Model.EF;

namespace PerformanceTest
{
    public abstract class EFRepository<T>  where T : class
    {
        public static readonly DbContext Context = new DosORMSqlServerEntities();

        public static DbSet<T> Entities
        {
            get { return Context.Set<T>(); }
        }

        public static List<T> GetAll()
        {
            return Entities.ToList();
        }
        public static List<T> Query(Expression<Func<T, bool>> where)
        {
            var result = Entities.Where(where);
            if (result.Any())
            {
                return result.ToList();
            }
            return new List<T>();
        }
        public static List<T> Top(int top)
        {
            var result = Entities.Take(top);
            return result.ToList();
        }
        public static int Insert(T entity)
        {
            Entities.Add(entity);
            return Context.SaveChanges();
        }
        public static int Insert(IEnumerable<T> entities)
        {
            foreach (var entity in entities)
            {
                Entities.Add(entity);
            }
            return Context.SaveChanges();
        }
        public static int Update(T entity)
        {
            Context.Entry(entity).State = System.Data.Entity.EntityState.Modified;
            return Context.SaveChanges();
        }
        public static int Update(IEnumerable<T> entities)
        {
            foreach (var entity in entities)
            {
                Context.Entry(entity).State = System.Data.Entity.EntityState.Modified;
            }
            return Context.SaveChanges();
        }
        public static int Delete(T entity)
        {
            Context.Entry(entity).State = System.Data.Entity.EntityState.Deleted;
            return Context.SaveChanges();
        }
        public static int Delete(IEnumerable<T> entities)
        {
            foreach (var entity in entities)
            {
                Context.Entry(entity).State = System.Data.Entity.EntityState.Deleted;
            }
            return Context.SaveChanges();
        }
    }
}

Un jardin potager ou potager est un jardin ou une partie de jardin où se pratique la culture vivrière de plantes potagères destinées à la consommation familiale, soit principalement des légumes, des fruits non cultivables en verger et des plantes aromatiques. Le jardin potager, en plus de sa fonction alimentaire et de son intérêt économique peut avoir un rôle ornemental, une vocation éducative, constituer une activité de loisir bonne pour la santé physique et morale et contribuer au maintien de la biodiversité animale et végétale.

Histoire 
Ce type de culture de plantes alimentaires et potagères et d'histoire de la sélection végétale remonte à la période préhistorique de la révolution néolithique de l'humanité, avec l'invention de l'agriculture par les chasseurs-cueilleurs du Néolithique. Elle s'est progressivement enrichie durant la période des jardins médiévaux et de l'exploration de monde, avec les découvertes des différents légumes et leurs proliférations dans le monde.

Motivations et aspects économiques 
Pendant les périodes de pénurie, notamment pendant les guerres, les jardins potagers permettent d'assurer une production alimentaire complémentaire. Plus récemment c'est le plaisir de produire soi-même des fruits et des légumes qui est le plus souvent la première motivation des jardiniers. Pour les habitants des villes (ou des zones périurbaines) et du fait du confinement imposé par la crise du Covid-19, le jardinage a connu un nouvel essor  car il permet de faire de l'exercice physique et de passer du temps à l'extérieur, surtout pour des populations plus jeunes.

Le poids économique et alimentaire des jardins potagers est loin d'être négligeable. Dans la France contemporaine, l'Insee les prends en compte lors des enquêtes sur la consommation des ménages. En 1994, selon l'Insee, les productions d'un potager permettent à un ménage d'assurer 41 % de son budget en fruits et légumes; cette proportion est plus élevée dans les jardins ouvriers et familiaux. Au début d es années 2000, l'autoconsommation s'établirait à 23 % des dépenses par personne en  légumes et à 12 % en fruits.

Types de jardins 

Différents types de jardins potagers peuvent être distingués : 
 jardin potager privatif en zone rurale, en zone urbaine ;
 jardin familial ou collectif situé dans un ensemble de jardins, autrefois dénommé « jardin ouvrier » ;
 jardin partagé, communautaire ou associatif ;
 jardin potager situé dans un environnement paysager tel qu'un château, parc ;
 jardin potager pédagogique ;
 jardin potager à visée thérapeutique ;
 jardin d'insertion ;
 jardin spatial ;
 etc.

